/**
 * Cloudflare entry point for the admin: the OpenNext worker for every request,
 * plus the two daily jobs that ran as Vercel Cron (see vercel.json). Each cron
 * trigger in wrangler.jsonc calls its route the same way Vercel did, with
 * CRON_SECRET as a bearer token.
 */

// @ts-expect-error - generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

const JOBS: Record<string, string> = {
  '0 6 * * *': '/api/instagram/sync',
  '0 7 * * *': '/api/cron/reminders',
};

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}

export default {
  fetch: handler.fetch,

  async scheduled(event: { cron: string }, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const path = JOBS[event.cron];
    if (!path) return;
    const headers: Record<string, string> = {};
    if (env.CRON_SECRET) headers.authorization = `Bearer ${env.CRON_SECRET}`;
    const req = new Request(`https://admin.ta-nnin.be${path}`, { headers });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => {
        if (!res.ok) console.error(`cron ${path} failed: ${res.status} ${await res.text()}`);
      }),
    );
  },
};
